def load(path):
    with open(path,'rb') as f: data=f.read()
    assert data[:4]==b'\x7fELF' and data[4]==2
    en = '<' if data[5]==1 else '>'
    e_phoff = struct.unpack_from(en+'Q', data, 0x20)[0]
    e_phentsize = struct.unpack_from(en+'H', data, 0x36)[0]
    e_phnum = struct.unpack_from(en+'H', data, 0x38)[0]
    ph=[]
    for i in range(e_phnum):
        off=e_phoff+i*e_phentsize
        p_type,p_flags,p_offset,p_vaddr,p_paddr,p_filesz,p_memsz,p_align = struct.unpack_from(en+'IIQQQQQQ',data,off)
        ph.append((p_type,p_flags,p_offset,p_vaddr,p_filesz))
    return data, ph

def find_vaddr(data, ph, s):
    # find all occurrences of byte string s, return vaddrs in PT_LOAD
    out=[]; start=0
    while True:
        i = data.find(s, start)
        if i<0: break
        start = i+1
        for t,fl,off,va,sz in ph:
            if t==1 and off<=i<off+sz:
                out.append(va+(i-off)); break
    return out

def xref_adrp_add(md, data, ph, target_va, text_range):
    """scan .text for adrp x, page ; add x, x, imm computing target_va"""
    res=[]
    t_off,t_va,t_sz = text_range
    code = data[t_off:t_off+t_sz]
    regs = {}  # per-instruction adrp base tracked naively: scan pairs
    for insn in md.disasm(code, t_va):
        if insn.mnemonic=='adrp':
            rn = insn.op_str.split(',')[0]
            page = int(insn.op_str.split('#')[1],16) if '#' in insn.op_str else int(insn.op_str.split(',')[1],16)
            regs[rn]=page
        elif insn.mnemonic=='add':
            parts=[p.strip() for p in insn.op_str.split(',')]
            if len(parts)==3 and parts[1] in regs and parts[2].startswith('#'):
                val = regs[parts[1]] + int(parts[2][1:],16)
                if val == target_va:
                    res.append(insn.address)
        elif insn.mnemonic in ('b','bl','ret','cbz','cbnz','tbz','tbnz'):
            regs={}
    return res

