import struct, sys
from capstone import *

def load(path):
    with open(path,'rb') as f: data=f.read()
    assert data[:4]==b'\x7fELF' and data[4]==2
    en = '<' if data[5]==1 else '>'
    return data, en

def sections(data, en):
    e_shoff = struct.unpack_from(en+'Q', data, 0x28)[0]
    e_shentsize = struct.unpack_from(en+'H', data, 0x3A)[0]
    e_shnum = struct.unpack_from(en+'H', data, 0x3C)[0]
    e_shstrndx = struct.unpack_from(en+'H', data, 0x3E)[0]
    secs=[]
    for i in range(e_shnum):
        off=e_shoff+i*e_shentsize
        name,typ,flags,addr,offset,size,link,info,align,entsize = struct.unpack_from(en+'IIQQQQIIQQ', data, off)
        secs.append([name,typ,flags,addr,offset,size,link,entsize])
    shstr_off = secs[e_shstrndx][4]
    for s in secs:
        end=data.find(b'\x00', shstr_off+s[0])
        s[0]=data[shstr_off+s[0]:end].decode('latin1')
    return secs

def get_md():
    md=Cs(CS_ARCH_ARM64, CS_MODE_ARM)
    md.skipdata=True
    return md

def sec_bytes(data, secs, name):
    for nm,typ,flags,addr,offset,size,link,entsize in secs:
        if nm==name:
            return data[offset:offset+size], addr
    return None, None

def find_string_vaddr(data, secs, s, secname='.rodata'):
    out=[]
    blob, base = sec_bytes(data, secs, secname)
    start=0
    while True:
        i=blob.find(s,start)
        if i<0: break
        out.append(base+i); start=i+1
    return out

def xref_str(data, secs, target):
    """find adrp/add pairs referencing target; scan .text"""
    text, tbase = sec_bytes(data, secs, '.text')
    md=get_md()
    res=[]
    regs={}
    for insn in md.disasm(text, tbase):
        if insn.mnemonic=='adrp':
            try:
                rn, imm = insn.op_str.split(',')
                regs[rn.strip()] = int(imm.strip(),16)
            except: pass
        elif insn.mnemonic=='add':
            parts=[p.strip() for p in insn.op_str.split(',')]
            if len(parts)==3 and parts[1] in regs and parts[2].startswith('#'):
                try:
                    val=regs[parts[1]]+int(parts[2][1:],16)
                    if val==target: res.append((insn.address, parts[0]))
                except: pass
            regs.pop(parts[0], None) if len(parts)>0 and parts[0] in regs and parts[0]!=parts[1] else None
        elif insn.mnemonic in ('b','bl','ret'):
            regs={}
    return res
