from arm2 import *

def symtab(data, secs, en):
    import struct
    syms=[]
    for nm,typ,flags,addr,offset,size,link,entsize in secs:
        if nm=='.symtab':
            strtab=None
            for nm2,typ2,fl2,a2,o2,s2,l2,e2 in secs:
                if nm2=='.strtab': strtab=data[o2:o2+s2]
            for i in range(size//entsize):
                off=offset+i*entsize
                st_name,st_info,st_other,st_shndx,st_value,st_size = struct.unpack_from(en+'IBBHQQ', data, off)
                end=strtab.find(b'\x00', st_name)
                name=strtab[st_name:end].decode('latin1')
                syms.append((name, st_value, st_size, st_info))
    return syms

def func_at(syms, addr):
    best=None
    for name,val,size,info in syms:
        if val<=addr and (info&0xf)==2:  # STT_FUNC
            if best is None or val>best[1]: best=(name,val,size)
    return best

